-- disciplines: 7 rows
UPDATE materials m SET disciplines = v.val, updated_at = NOW()
FROM jsonb_to_recordset($fix$[{"category":"kayak","brand":"Bliss-Stick","model":"Blitz","variant":null,"size":null,"val":["playboat"]},{"category":"kayak","brand":"Bliss-Stick","model":"Blitz Special","variant":null,"size":null,"val":["playboat"]},{"category":"kayak","brand":"Bliss-Stick","model":"RAD (Radical Aerial Device)","variant":null,"size":"175","val":["playboat"]},{"category":"kayak","brand":"Bliss-Stick","model":"RAD (Radical Aerial Device)","variant":null,"size":"185","val":["playboat"]},{"category":"kayak","brand":"Bliss-Stick","model":"RAD (Radical Aerial Device)","variant":null,"size":"195","val":["playboat"]},{"category":"kayak","brand":"Bliss-Stick","model":"S.C.U.D.","variant":null,"size":null,"val":["creek"]},{"category":"kayak","brand":"Riot","model":"Thunder","variant":null,"size":"65","val":["river_runner"]}]$fix$::jsonb) AS v(category material_category, brand text, model text, variant text, size text, val material_discipline[])
WHERE m.category = v.category
