FROM jsonb_to_recordset($fix$[{"category":"kayak","brand":"Robson","model":"Supersonic","variant":null,"size":null,"val":"Specs and year_from (model year) from playak.com buyers guide (secondary source). year_to unknown: maker site (Wayback 2012-04) lists only touring, sit-on-top and SUP boats, no whitewater; no dated end found paddler_weight_max_kg as published: 50."}]$fix$::jsonb) AS v(category material_category, brand text, model text, variant text, size text, val text)
