{"category":"kayak","brand":"Spade","model":"Spicy","variant":null,"size":null,"url":"https://cdn.prod.website-files.com/687620c1990b182da55dc137/68937575db07fe982f97b789_Joker_side_blue.png"},{"category":"kayak","brand":"Spade","model":"Spicy","variant":null,"size":null,"url":"https://cdn.prod.website-files.com/687620c1990b182da55dc137/6893759b6bd2cec13a4d35a4_jokerheader.jpg"},{"category":"paddle","brand":"Sawyer","model":"Copperhead II","variant":"straight","size":null,"url":"https://d2qyesv2yl91ku.cloudfront.net/images/products/Sawyer-Paddles-Oars/Copperhead-II-Kayak-Paddle-2.png"},{"category":"paddle","brand":"Sawyer","model":"Copperhead II","variant":"cranked","size":null,"url":"https://d2qyesv2yl91ku.cloudfront.net/images/products/Sawyer-Paddles-Oars/Copperhead-II-Kayak-Paddle-2.png"},{"category":"paddle","brand":"Sawyer","model":"Crosscut IV","variant":null,"size":null,"url":"https://d2qyesv2yl91ku.cloudfront.net/images/products/Sawyer-Paddles-Oars/CrossCut_Left_Up.png"}]$fix$::jsonb) AS v(category material_category, brand text, model text, variant text, size text, url text) ON TRUE
WHERE m.category = v.category
  AND lower(btrim(m.brand)) = lower(btrim(v.brand))
  AND lower(btrim(m.model)) = lower(btrim(v.model))
  AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(v.variant, '')))
  AND lower(btrim(COALESCE(m.size, ''))) = lower(btrim(COALESCE(v.size, '')))
  AND m.created_by = 'system-catalogue'
  AND i.material_id = m.id AND i.source_url = v.url
  AND i.source_kind <> 'user' AND i.status <> 'removed';
